examples.template:
MonarchButton({{trigger}}) { isPresented = true }
    .sheet(isPresented: $isPresented) {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    Text({{description}})
                        .monarchTextStyle(.body)
                        .foregroundStyle(theme.colors.textMuted)
                    LabeledContent("Operation") {
                        HStack(spacing: theme.spacing.space2) {
                            MonarchMethodBadge({{request.method}})
                            Text({{request.path}}).monarchTextStyle(.code)
                        }
                    }
                    LabeledContent("Status") {
                        HStack(spacing: theme.spacing.space2) {
                            MonarchStatusBadge(MonarchStatusDefinition(String({{request.status}}), tone: tone({{request.status}})), size: .sm)
                            Text({{request.errorCode}}).monarchTextStyle(.code)
                        }
                    }
                    LabeledContent("Request ID") {
                        HStack(spacing: theme.spacing.space1) {
                            Text(verbatim: {{request.id}}).monarchTextStyle(.code)
                            MonarchCopyButton(value: {{request.id}}, target: "request ID", variant: .ghost, isIconOnly: true)
                        }
                    }
                    LabeledContent("Time") {
                        Text(RelativeDateTimeFormatter().localizedString(for: Date().addingTimeInterval(-{{request.minutesAgo|double}} * 60), relativeTo: Date()))
                            // A dotted underline marks the time that shows the exact moment on the web.
                            .underline(pattern: .dot)
                    }
                    LabeledContent("Duration") {
                        Text("\({{request.durationMs}}) ms")
                    }
                    LabeledContent({{fields.0.label}}) {
                        Text({{fields.0.value}})
                    }
                    LabeledContent({{fields.1.label}}) {
                        HStack(spacing: theme.spacing.space1) {
                            Text(verbatim: {{fields.1.value}}).monarchTextStyle({{fields.1.mono}} ? .code : .body)
                                .foregroundStyle(theme.colors.textDefault)
                            MonarchCopyButton(value: {{fields.1.copyValue}}, target: {{fields.1.label}}, variant: .ghost, isIconOnly: true)
                        }
                    }
                    LabeledContent({{fields.2.label}}) {
                        Text({{fields.2.value}})
                    }
                }
                .labeledContentStyle(.monarch)
                .padding(theme.spacing.space4)
            }
            .navigationTitle({{title}})
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("Close") { isPresented = false }
                }
            }
        }
        .presentationDetents([.medium, .large])
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isPresented = false

/// The tone of an HTTP status: 2xx success, 3xx info, 4xx warning, 5xx danger.
private func tone(_ status: Int) -> MonarchTone {
    switch status {
    case 500...: .danger
    case 400..<500: .warning
    case 300..<400: .info
    case 200..<300: .success
    default: .neutral
    }
}

